package middleware

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// Hidden F2P regression test (ADR-0032.1 S4). httpFancyWriter.ReadFrom must
// not double-count bytes when a Tee writer routes writes through
// basicWriter.Write (which already increments the counter).
func TestGHXReadFromTeeByteCount(t *testing.T) {
	original := &httptest.ResponseRecorder{HeaderMap: make(http.Header), Body: new(bytes.Buffer)}
	f := &httpFancyWriter{basicWriter: basicWriter{ResponseWriter: original}}
	var teeBuf bytes.Buffer
	f.Tee(&teeBuf)
	const input = "hello world"
	n, err := f.ReadFrom(strings.NewReader(input))
	if err != nil {
		t.Fatalf("ReadFrom error: %v", err)
	}
	if n != int64(len(input)) {
		t.Fatalf("ReadFrom n = %d, want %d", n, len(input))
	}
	if got := f.BytesWritten(); got != len(input) {
		t.Fatalf("BytesWritten() = %d, want %d (bug double-counts)", got, len(input))
	}
	if !bytes.Equal(teeBuf.Bytes(), []byte(input)) {
		t.Fatalf("tee buffer = %q, want %q", teeBuf.Bytes(), input)
	}
}
GHXEOF
